def fusionner(intervalles):
    if not intervalles:
        return []

    triés = sorted(intervalles, key=lambda x: (x[0], x[1]))
    fusionnés = [triés[0]]

    for debut, fin in triés[1:]:
        dernier_debut, dernier_fin = fusionnés[-1]
        if debut <= dernier_fin:
            fusionnés[-1] = (dernier_debut, max(dernier_fin, fin))
        else:
            fusionnés.append((debut, fin))

    return fusionnés
